import json, collections

events = [json.loads(l) for l in open("observed_run/tool_traces.jsonl")]
grades = [e for e in events if e["event"] == "grade"]

# map trajectory_id -> (mode, case) using any event with those fields
meta = {}
for e in events:
    if "case_id" in e and "mode" in e:
        meta[e.get("trajectory_id")] = (e["mode"], e["case_id"])
    elif e.get("trajectory_id") and e.get("trajectory_id") not in meta and "event" in e:
        pass

groups = collections.defaultdict(list)
for g in grades:
    mode, case = meta[g["trajectory_id"]]
    groups[(mode, case)].append(g["reward"])

print(f"{'mode':6} {'case':14} rewards-per-round")
for k in sorted(groups):
    print(f"{k[0]:6} {k[1]:14} {groups[k]}")
EOF

